import{_ as r,l as t,o as e,c as s,v as o,p as n,x as l,d,i as c,S as m}from"./chunks/framework.InCnrqk-.js";const O=JSON.parse('{"title":"OOM killer","description":"","frontmatter":{"title":"OOM killer","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/oom-killer.md","filePath":"cs/oom-killer.md","lastUpdated":1789023840000}'),p={name:"cs/oom-killer.md"};function h(E,a,_,u,B,f){const i=t("Mermaid");return e(),s("div",null,[a[1]||(a[1]=o('<h1 id="oom-killer" tabindex="-1">OOM killer <a class="header-anchor" href="#oom-killer" aria-label="Permalink to &quot;OOM killer&quot;">​</a></h1><div class="epigraph"><p>内核无法再满足缺页或内核分配时，必须选一个用户进程杀掉，释放其页；否则整机锁死在分配路径上。</p><footer>—— 据 Silberschatz 对内存耗尽的讨论；Linux 对 oom_kill 策略的整理</footer></div><p><a href="/cs/swap-device">上一课</a>在槽耗尽时失败。<a href="/cs/thrashing">抖动</a>可以挂起进程，挂起仍占交换与一些内核元数据。内核自己的分配（页表、缓冲）失败没有「返回 NULL 给 malloc」那么简单：可能正持有锁。<a href="/cs/buddy-allocator">buddy</a> 尚未讲，但无空闲页是同一危机。缺口是<strong>选牺牲进程</strong>：可杀掉谁、按什么分、不能杀谁。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>若随机杀，可能杀掉 init 或正在写回的关键任务，系统无法收场。若从不杀，所有分配者睡眠等待，形成死等。缺口：打分（占用匿名页多、nice 低、不是 init）选出 victim，发送致命信号，等待其退出路径释放页表与文件。<a href="/cs/signals">信号</a>课会细讲递送；这里只需「杀进程是回收帧的最后手段」。</p><p>本课不把每版 Linux <code>oom_score_adj</code> 的整数表背完。</p><p><span class="marginnote">牺牲的是进程，不是某一页。杀完可能仍不够，再选下一个。内核线程通常不可杀；预留内存给紧急路径，避免杀的过程自己再分配失败。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>分配器在回收、写回、压缩都试过后仍失败，进入 OOM。计算各进程分数，排除不可杀者，选定后投递 <code>SIGKILL</code>（不可捕获）。退出后帧回到空闲。用户也可对某作业预先调高分数，表示「宁可杀我」。不要在缺页路径上无限重试而不设上限。</p>',9)),(e(),n(m,null,{default:l(()=>[c(i,{id:"mermaid-25",class:"mermaid",graph:"flowchart%20TD%0A%20%20FAIL%5B%22%E5%88%86%E9%85%8D%E5%BD%BB%E5%BA%95%E5%A4%B1%E8%B4%A5%22%5D%20--%3E%20SCORE%5B%22%E6%8C%89%E5%8D%A0%E7%94%A8%E4%B8%8E%E4%BC%98%E5%85%88%E7%BA%A7%E6%89%93%E5%88%86%22%5D%0A%20%20SCORE%20--%3E%20KILL%5B%22SIGKILL%20%E7%89%BA%E7%89%B2%E8%BF%9B%E7%A8%8B%22%5D%0A%20%20KILL%20--%3E%20FREE%5B%22%E9%80%80%E5%87%BA%E5%9B%9E%E6%94%B6%E9%A1%B5%22%5D%0A"})]),fallback:l(()=>[...a[0]||(a[0]=[d(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=o('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>OOM 把虚存从「自动 Cache」接到进程生命周期：帧最终属于进程映像，回收映像才能保证前进。它与死锁课不同：不是锁顺序，是资源耗尽。与安全课的「杀进程」也不同：这里不是审计攻击，是保机器可运行。工作集再漂亮，Σ 承诺超过物理加 swap，仍会走到这里——承诺从哪来，下一课过度提交。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不引入 cgroup 内 OOM（memcg）的全部层次，只承认可以先在一组作业内杀。不把用户空间 oomd 写成内核替代。也不讨论如何用 OOM 做对抗；只讲内核分配失败的回收。杀错进程会导致服务中断，这是运维边界，课内只要求有可解释的分数。</p><p>后课默认：最后手段是杀进程。为何 <code>malloc</code> 当时成功、稍后才爆，下一课过度提交。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>帧与 swap 双尽时杀进程回收，避免分配路径死等。</li><li>打分避开 init；<code>SIGKILL</code> 不可捕获。</li><li>成功分配与真正占帧之间的缺口是过度提交。</li><li>出处：Silberschatz et al., <em>OSC</em>；Linux mm 文档（oom）；Tanenbaum <em>MOS</em>。</li></ul>',7))])}const k=r(p,[["render",h]]);export{O as __pageData,k as default};
